<section class="hero"><h1>Faturat</h1><p><?=number_format($result['total'])?> fatura<?= $jobId?' në job #'.(int)$jobId:''?>.</p></section>
<section class="panel"><form method="get" class="filters"><label class="field">Viti<input type="number" name="year" min="2000" max="2100" value="<?=$year?>"></label><label class="field">Kërko<input name="q" value="<?=e($query)?>" placeholder="Faturë, UNIREF, biznes, NRB"></label><label class="field">Rreshta<select name="per_page"><?php foreach([20,30,40,50,100] as $size):?><option value="<?=$size?>" <?=$result['per_page']===$size?'selected':''?>><?=$size?></option><?php endforeach;?></select></label><?php if($jobId):?><input type="hidden" name="job" value="<?=$jobId?>"><?php endif;?><button>Kërko</button></form></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Fatura</th><th>Biznesi</th><th>Data</th><th>Shuma</th><th>Paguar</th><th>Mbeten</th><th>Statusi</th><th>Veprime</th></tr></thead><tbody><?php foreach($result['rows'] as $invoice):?><tr><td><?=e($invoice['invoice_number'])?><br><small><?=e($invoice['uniref'])?></small></td><td><?=e($invoice['registration_number'].' · '.$invoice['legal_name'])?></td><td><?=e($invoice['issued_on'])?></td><td><?=number_format((float)$invoice['amount'],2)?> EUR</td><td><?=number_format((float)$invoice['paid_amount'],2)?> EUR</td><td><?=number_format((float)$invoice['outstanding'],2)?> EUR</td><td><span class="badge"><?=e($invoice['status_code'])?></span></td><td><a class="button" href="<?=e(app_url('/admin/finance/invoice-pdf.php?id='.(int)$invoice['id']))?>">PDF</a><form method="post" action="<?=e(app_url('/admin/finance/email-invoice.php'))?>"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><input type="hidden" name="invoice_id" value="<?=(int)$invoice['id']?>"><input type="email" name="email" placeholder="Email opsional"><button>Dërgo</button></form></td></tr><?php endforeach;?></tbody></table><?php if($result['rows']===[]):?><div class="empty">Nuk u gjetën fatura.</div><?php endif;?></div><?php $base=['year'=>$year,'per_page'=>$result['per_page'],'q'=>$query]+($jobId?['job'=>$jobId]:[]);?><nav class="pagination"><?php if($result['page']>1):?><a class="button" href="?<?=e(http_build_query($base+['page'=>$result['page']-1]))?>">Mëparshme</a><?php endif;?><span>Faqja <?=$result['page']?> / <?=$result['pages']?></span><?php if($result['page']<$result['pages']):?><a class="button" href="?<?=e(http_build_query($base+['page'=>$result['page']+1]))?>">Tjetra</a><?php endif;?></nav></section>
